"""Elementary physical S-wave masters and the exact source sine transform.

All 50 monomial directions are retained. The inverse-transpose phase map
uses its exact orthogonality identity, without numerical inversion.
"""
from fractions import Fraction as F
import gzip
import json
from math import comb
import re

from .partial_wave_master_prototype import elementary_K0


def ball(value):
    from flint import arb
    value=F(str(value));return arb(value.numerator)/value.denominator


def binomial_differences(pool):
    """Integral of (u-1)^n from the complete moments of u^b."""
    return [sum(((-1)**(n-b)*comb(n,b)*pool[b] for b in range(n+1)),pool[0]*0)
            for n in range(len(pool))]


def elementary_s_wave_moments(s,u0,degree):
    """Return J_n^0 for n=0..degree at s>4 and u0=4/(sqrt(s)+2).

    The caller supplies consistent enclosing s/u0 parameters. n=0 is
    exactly one half, including before the binomial transformation.
    """
    from flint import arb
    if not isinstance(degree,int) or degree<1 or not s>4 or not 0<u0<1:
        raise ValueError('Physical s>4,0<u0<1 and positive integer degree required')
    logarithm=u0.log()
    pool=[arb(1)/2]+[elementary_K0(n,s,u0,logarithm) for n in range(1,degree+1)]
    moments=binomial_differences(pool)
    if moments[0]!=arb(1)/2:raise ArithmeticError('Constant S-wave moment lost exact normalization')
    return moments


def source_parameters(node,M=50):
    if not isinstance(M,int) or M<2 or not isinstance(node,int) or not 0<=node<M:
        raise ValueError('A valid exact source midpoint is required')
    theta=F(2*node+1,4*M);cosine=ball(theta).cos_pi()
    return theta,4/(cosine*cosine),(1-cosine)/(1+cosine),2*cosine/(1+cosine)


def exact_source_sine_matrix(M=50):
    """Same modular rational-angle phase convention as the frozen factors."""
    from flint import arb_mat
    if not isinstance(M,int) or M<2:raise ValueError('M>=2 is required')
    cache={q:ball(F(q,2*M)).sin_pi() for q in range(4*M)}
    T=arb_mat(M,M,[cache[((2*j+1)*n)%(4*M)] for j in range(M) for n in range(1,M+1)])
    if any(T[j,M-1]!=(-1)**j or not T[j,M-1].is_exact() for j in range(M)):
        raise ArithmeticError('Exact Nyquist column lost')
    return T


def source_inverse_transpose(T):
    """T^-T=T diag(2/M,...,2/M,1/M), for the exact source sine matrix.

    T must be an enclosure of this analytic matrix, not an arbitrary square
    matrix. The identity follows from T^T T=diag(M/2,...,M/2,M).
    """
    from flint import arb_mat
    M=T.nrows()
    if M<2 or T.ncols()!=M:raise ValueError('A square source sine matrix is required')
    return arb_mat(M,M,[T[i,j]*ball(F(1 if j==M-1 else 2,M)) for i in range(M) for j in range(M)])


def read_physical_wave_prefix(path,wave=(2,0),*,chunk_size=1024**2):
    """Read the desired leading wave from the authenticated source JSON format.

    The caller authenticates the complete compressed file first. Source files
    place their final top-level rows array after the header; no other rows or
    scalar coefficients are reconstructed by this targeted comparison reader.
    """
    decoder=json.JSONDecoder();marker=re.compile(r',\s*"rows"\s*:\s*\[')
    with gzip.open(path,'rt') as stream:
        buffer=''
        while True:
            block=stream.read(chunk_size)
            if not block:raise ValueError('Incomplete source header')
            buffer+=block
            match=marker.search(buffer)
            if match:break
            if len(buffer)>20*1024**2:
                raise ValueError('Expected final source rows array not found')
        header=json.loads(buffer[:match.start()]+'}')
        buffer=buffer[match.end():];decoded=0
        while True:
            buffer=buffer.lstrip()
            if buffer.startswith(','):buffer=buffer[1:].lstrip()
            if buffer.startswith(']'):raise ValueError('Requested source wave absent')
            try:
                row,end=decoder.raw_decode(buffer)
            except json.JSONDecodeError:
                block=stream.read(chunk_size)
                if not block:raise ValueError('Incomplete source wave object')
                buffer+=block
                continue
            decoded+=1
            if (row.get('isospin'),row.get('ell'))==tuple(wave):
                return header,row,decoded
            buffer=buffer[end:]


def exact_ball_endpoints(encoded):
    if encoded is None:return F(0),F(0)
    midpoint=F(int(encoded[0][0],16))*F(2)**encoded[0][1]
    radius=F(int(encoded[1][0],16))*F(2)**encoded[1][1]
    if radius<0:raise ValueError('Negative serialized radius')
    return midpoint-radius,midpoint+radius


def compare_half_coefficient(old_encoded,new_encoded):
    """Compare J0 to one half of the registered I2/S0 single_s coefficient."""
    lo,hi=exact_ball_endpoints(old_encoded);lo/=2;hi/=2
    new_lo,new_hi=exact_ball_endpoints(new_encoded)
    if max(lo,new_lo)>min(hi,new_hi):return 'disjoint'
    if (lo,hi)==(new_lo,new_hi):return 'equal_intervals'
    if lo<=new_lo and new_hi<=hi:return 'archive_half_contains_new_J0'
    if new_lo<=lo and hi<=new_hi:return 'new_J0_contains_archive_half'
    return 'overlapping_neither_contains'

"""Bounded exact-structure prototype for fixed-spin pion partial-wave masters.

This module does not replace production projection or discard coefficients.
Its recurrence is exact over the supplied scalar field; interval inputs give
enclosures and expose, rather than suppress, recurrence amplification.
"""
from fractions import Fraction as F
from math import comb

from .amplitudes import basis_labels


def reconstruct_moments(J,H,s,ell):
    """Recover M[n,m] from J[n]=M[n,0], H[n]=M[n,1], n=1..N."""
    J,H=list(J),list(H);N=len(J)
    if not N or len(H)!=N or not isinstance(ell,int) or ell<0:
        raise ValueError('Matching nonempty master edges and nonnegative integer spin required')
    epsilon=-1 if ell%2 else 1
    zero=J[0]*0;one=zero+1
    matrix=[[zero for _ in range(N+1)] for _ in range(N+1)]
    matrix[0][0]=one/2 if ell==0 else zero
    if epsilon==-1:
        compatible=H[0].contains(0) if hasattr(H[0],'contains') else H[0]==0
        if not compatible:raise ValueError('Odd-spin diagonal H1 must enclose zero')
    for n in range(1,N+1):
        matrix[n][0]=J[n-1];matrix[0][n]=epsilon*J[n-1]
        matrix[n][1]=H[n-1];matrix[1][n]=epsilon*H[n-1]
    if epsilon==-1:matrix[1][1]=zero
    a=2*(s+4)/(s-4);b=4*(s+12)/(s-4)
    for n in range(2,N+1):
        for m in range(2,n+1):
            if epsilon==-1 and n==m:
                value=zero
            else:
                value=-(matrix[n-2][m-2]+matrix[n][m-2]+matrix[n-2][m]
                    +a*(matrix[n-1][m-2]+matrix[n-2][m-1]+matrix[n][m-1]+matrix[n-1][m])
                    +b*matrix[n-1][m-1])
            matrix[n][m]=value;matrix[m][n]=epsilon*value
    return matrix


def assemble_isospin_row(moments,zs,degree,ell,isospin,phase_powers=None):
    """Assemble exactly the repository's full tensor-product source basis."""
    if len(moments)!=degree+1 or any(len(row)!=degree+1 for row in moments):
        raise ValueError('Moment matrix shape does not match degree')
    if isospin not in (0,1,2):raise ValueError('Isospin must be0,1,2')
    epsilon=-1 if ell%2 else 1;constant=moments[0][0];zero=constant*0
    if ell%2!=(isospin==1):return [zs*0 for _ in basis_labels(degree)]
    powers=[zs*0+1] if phase_powers is None else list(phase_powers)
    if phase_powers is None:
        for _ in range(degree):powers.append(powers[-1]*zs)
    elif len(powers)!=degree+1:raise ValueError('Phase-power count does not match degree')
    row=[]
    for kind,n,m in basis_labels(degree):
        if kind=='constant':A=B=constant
        elif kind=='single_s':A=powers[n]*constant;B=moments[n][0]
        elif kind=='single_tu':A=(1+epsilon)*moments[n][0];B=powers[n]*constant+epsilon*moments[n][0]
        elif kind=='double_s_tu':
            A=(1+epsilon)*powers[n]*moments[m][0]
            B=powers[m]*moments[n][0]+moments[n][m]
        elif kind=='double_tu':
            A=(1+epsilon)*moments[n][m]/2
            B=epsilon*(powers[n]*moments[m][0]+powers[m]*moments[n][0])/2
        else:raise ValueError('Unknown basis label')
        row.append(3*A+(1+epsilon)*B if isospin==0 else
                   ((1-epsilon)*B if isospin==1 else (1+epsilon)*B))
    return row


def laurent_legendre_coefficients(s,ell):
    """Exact dict exponent->coefficient for P_ell(1+32/d*(u^-1-u^-2))."""
    if not isinstance(ell,int) or ell<0:raise ValueError('Nonnegative integer spin required')
    s=F(s);z={0:F(1),-1:32/(s-4),-2:-32/(s-4)}
    previous={0:F(1)}
    if ell==0:return previous
    current=z
    for n in range(1,ell):
        product={}
        for i,a in z.items():
            for j,b in current.items():product[i+j]=product.get(i+j,F(0))+a*b
        following={i:(2*n+1)*v/(n+1) for i,v in product.items()}
        for i,v in previous.items():following[i]=following.get(i,F(0))-F(n,n+1)*v
        previous,current=current,{i:v for i,v in following.items() if v}
    return current


def K_combination_coefficients(s,ell,n):
    """Jn or Hn as a linear combination of K_r^0 or K_r^1 respectively."""
    if not isinstance(n,int) or n<0:raise ValueError('Nonnegative integer exponent required')
    output={}
    for a,value in laurent_legendre_coefficients(s,ell).items():
        for b in range(n+1):
            exponent=a+b
            output[exponent]=output.get(exponent,F(0))+value*comb(n,b)*(-1 if (n-b)%2 else 1)
    return {k:v for k,v in output.items() if v}


def elementary_K0(r,s,lower,log_lower):
    """First member of the universal K pair; supply u_min=4/(sqrt(s)+2)."""
    if not isinstance(r,int):raise ValueError('An integer exponent is required')
    if r==1:return 8/(s-4)*(2/lower-2+log_lower)
    if r==2:return 8/(s-4)*(lower-1-2*log_lower)
    return 8/(s-4)*(2*(1-lower**(r-2))/(r-2)-(1-lower**(r-1))/(r-1))
